// One-time secrets (secret.ts): the reference vectors secrets and secretNegative of
// internal/tte2/testdata/vectors.json, generated by the Go reference, then unit tests of the rules.

import { describe, expect, it } from 'vitest';
import vectors from '../../../../internal/tte2/testdata/vectors.json';
import { decryptBytes } from './decrypt';
import { isE2EError, type E2EErrorCode } from './errors';
import { encodeMetadata, openMetadata, sealMetadataRaw } from './sealed';
import {
  ENCODED_PASSPHRASE_SALT_SIZE,
  MAX_PASSPHRASE_SIZE,
  MAX_SECRET_ENCODED_SIZE,
  MAX_SECRET_RUNES,
  MIN_SECRET_ENCODED_SIZE,
  PASSPHRASE_ITERATIONS,
  checkSecretFraming,
  decodePassphraseSalt,
  deriveSecretKey,
  encodeProof,
  newPassphraseDescriptor,
  openSecret,
  parseProof,
  sealSecret,
  sealSecretRaw,
  secretKeyProof,
  secretProof,
  secretTextIsEmpty,
  secretVerifier,
  type PassphraseDescriptor,
} from './secret';
import { importTransferKey, parseKey, prepareFileEncryption } from './tte2';
import {
  firstDifference,
  fromBase64,
  fromHex,
  goErrorName,
  pattern,
  sha256Hex,
  toHex,
} from './tte2-helpers.test-helper';

// PBKDF2 at 600 000 iterations takes a fraction of a second per derivation.
const SLOW = 30_000;

type SecretVector = (typeof vectors.secrets)[number];
type SecretNegative = (typeof vectors.secretNegative)[number];

const byName = new Map<string, SecretVector>(vectors.secrets.map((v) => [v.name, v]));

/** The descriptor of a vector, null when absent. */
function descriptorOf(v: { descriptor?: PassphraseDescriptor | undefined }): PassphraseDescriptor | null {
  return v.descriptor ?? null;
}

/** Constant-time-free test comparison of SHA-256(proof) with a verifier. */
async function matches(verifierHex: string, proof: Uint8Array): Promise<boolean> {
  return encodeProof(await secretVerifier(proof)) === verifierHex;
}

/** Returns the E2E code f throws or rejects with. */
async function codeOf(f: () => unknown): Promise<E2EErrorCode | 'none'> {
  try {
    await f();
    return 'none';
  } catch (err) {
    if (isE2EError(err)) return err.code;
    throw err;
  }
}

describe('secret vectors', () => {
  for (const v of vectors.secrets) {
    it(
      `${v.name}: derives the reference keys, proofs and blobs`,
      async () => {
        const key = parseKey(v.keyFragment);
        expect(toHex(key)).toBe(v.keyHex);
        const descriptor = descriptorOf(v);
        const passphrase = v.passphrase ?? '';
        let p = new Uint8Array(0);
        if (descriptor !== null) {
          const nfc = new TextEncoder().encode(passphrase.normalize('NFC'));
          expect(toHex(nfc)).toBe(v.passphraseNfcHex);
          expect(passphrase.normalize('NFC')).not.toBe(passphrase);
          const pk = await crypto.subtle.importKey('raw', nfc, 'PBKDF2', false, ['deriveBits']);
          p = new Uint8Array(
            await crypto.subtle.deriveBits(
              {
                name: 'PBKDF2',
                hash: 'SHA-256',
                salt: decodePassphraseSalt(descriptor.salt),
                iterations: PASSPHRASE_ITERATIONS,
              },
              pk,
              256,
            ),
          );
          expect(toHex(p)).toBe(v.passphraseKeyHex);
        }
        const root = await deriveSecretKey(key, passphrase, descriptor);
        expect(toHex(root)).toBe(v.rootKeyHex);
        const hk = await crypto.subtle.importKey('raw', key, 'HKDF', false, ['deriveBits']);
        const info = new TextEncoder().encode('transteira/tte2/v1/secret');
        const want = await crypto.subtle.deriveBits(
          { name: 'HKDF', hash: 'SHA-256', salt: p, info },
          hk,
          256,
        );
        expect(toHex(new Uint8Array(want))).toBe(v.rootKeyHex);

        const kp = await secretKeyProof(key);
        const pr = await secretProof(await importTransferKey(root));
        expect(encodeProof(kp)).toBe(v.keyProofHex);
        expect(encodeProof(pr)).toBe(v.proofHex);
        expect(encodeProof(await secretVerifier(kp))).toBe(v.keyVerifierHex);
        expect(encodeProof(await secretVerifier(parseProof(v.proofHex)))).toBe(v.verifierHex);

        expect(await sealSecret(root, v.text, { nonce: fromHex(v.textNonceHex) })).toBe(v.sealedText);
        expect(await openSecret(root, v.sealedText)).toBe(v.text);
        checkSecretFraming(v.sealedText);
        expect(secretTextIsEmpty(v.sealedText)).toBe(v.text === '');

        if (v.file !== undefined) {
          const f = v.file;
          const ct = fromBase64(f.ciphertextBase64);
          expect(ct.length).toBe(f.ciphertextLength);
          expect(await sha256Hex(ct)).toBe(f.ciphertextSha256Hex);
          const plain = pattern(f.plaintextLength);
          const enc = await prepareFileEncryption(root, 0, new Blob([plain]), {
            chunkSize: f.chunkSize,
            salt: fromHex(f.saltHex),
          });
          expect(firstDifference(await enc.range(0, enc.size), ct)).toBe(-1);
          expect(firstDifference(await decryptBytes({ key: root, index: 0 }, ct), plain)).toBe(-1);
          const { v: version, ...fields } = f.metadata;
          expect(version).toBe(1);
          const m = { path: '', ...fields };
          expect(encodeMetadata(m)).toBe(f.metadataPlaintext);
          const raw = new TextEncoder().encode(f.metadataPlaintext);
          expect(await sealMetadataRaw(root, 0, raw, { nonce: fromHex(f.metadataNonceHex) })).toBe(
            f.sealedMetadata,
          );
          const opened = await openMetadata(root, 0, f.sealedMetadata);
          expect(opened).toEqual(m);
          expect(opened.count).toBe(1);
          expect(opened.size).toBe(f.plaintextLength);
          expect(opened.sha256).toBe(f.plaintextSha256Hex);
        }
      },
      SLOW,
    );
  }

  for (const c of vectors.secretNegative as SecretNegative[]) {
    it(
      `negative ${c.name}: ${c.expectedError}`,
      async () => {
        const base = byName.get(c.secret)!;
        const key = fromHex(c.keyHex ?? base.keyHex);
        expect(await matches(base.keyVerifierHex, await secretKeyProof(key))).toBe(c.keyProofValid);
        const passphrase = c.passphrase ?? base.passphrase ?? '';
        const descriptor = c.noDescriptor === true ? null : (c.descriptor ?? descriptorOf(base));
        let proofValid = false;
        const name = await goErrorName(async () => {
          const root = await deriveSecretKey(key, passphrase, descriptor);
          proofValid = await matches(base.verifierHex, await secretProof(root));
          if (c.text !== undefined) {
            await sealSecret(root, c.text);
            return;
          }
          const sealed = c.sealed ?? base.sealedText;
          const framing = await codeOf(() => checkSecretFraming(sealed));
          expect(framing).toBe(c.expectedError === 'ErrEncoding' ? 'encoding' : 'none');
          await openSecret(root, sealed);
        });
        expect(name).toBe(c.expectedError);
        expect(proofValid).toBe(c.proofValid);
      },
      SLOW,
    );
  }
});

describe('secret rules', () => {
  const key = Uint8Array.from({ length: 32 }, (_, i) => i + 7);
  const descriptor: PassphraseDescriptor = {
    kdf: 'pbkdf2-sha256',
    iterations: PASSPHRASE_ITERATIONS,
    salt: 'lsSkl3ciGfnIEmp8IAWYQg',
  };

  it('has the bounds of the format', () => {
    expect(MIN_SECRET_ENCODED_SIZE).toBe(39);
    expect(MAX_SECRET_ENCODED_SIZE).toBe(53372);
  });

  it('draws a fresh descriptor', () => {
    const a = newPassphraseDescriptor();
    expect(a.salt).toHaveLength(ENCODED_PASSPHRASE_SALT_SIZE);
    expect(decodePassphraseSalt(a.salt)).toHaveLength(16);
    expect(newPassphraseDescriptor().salt).not.toBe(a.salt);
  });

  it(
    'refuses bad keys and passphrases',
    async () => {
      expect(await codeOf(() => deriveSecretKey(key.subarray(1), '', null))).toBe('invalid-key');
      for (const bad of ['a\ud800', '\udc00a', 'x'.repeat(MAX_PASSPHRASE_SIZE + 1), '']) {
        expect(await codeOf(() => deriveSecretKey(key, bad, descriptor))).toBe('invalid-passphrase');
      }
      expect(await codeOf(() => deriveSecretKey(key, 'a', null))).toBe('invalid-passphrase');
      for (const salt of [
        '',
        'lsSkl3ciGfnIEmp8IAWYQh',
        'lsSkl3ciGfnIEmp8IAWYQg=',
        'lsSkl3ciGfnIEmp8IAWY+g',
      ]) {
        expect(await codeOf(() => deriveSecretKey(key, 'a', { ...descriptor, salt }))).toBe(
          'invalid-passphrase',
        );
      }
      // Exactly MAX_PASSPHRASE_SIZE bytes after NFC; a decomposed form gives the same key.
      const long = 'é'.repeat(MAX_PASSPHRASE_SIZE / 2);
      const a = await deriveSecretKey(key, long, descriptor);
      expect(await deriveSecretKey(key, long.normalize('NFD'), descriptor)).toEqual(a);
    },
    SLOW,
  );

  it('parses proofs strictly', () => {
    const s = 'ab'.repeat(32);
    expect(encodeProof(parseProof(s))).toBe(s);
    for (const bad of ['', s.slice(1), s + '0', s.toUpperCase(), s.slice(0, 63) + 'g']) {
      expect(() => parseProof(bad)).toThrow(/invalid-secret/);
    }
  });

  it('seals and opens texts within the bounds', async () => {
    const root = await importTransferKey(key);
    const largest = '😀'.repeat(MAX_SECRET_RUNES);
    const s = await sealSecret(root, largest);
    expect(s).toHaveLength(MAX_SECRET_ENCODED_SIZE);
    expect(await openSecret(root, s)).toBe(largest);
    expect(await codeOf(() => checkSecretFraming(s + 'AAAA'))).toBe('encoding');
    expect(await codeOf(() => sealSecret(root, 'a'.repeat(MAX_SECRET_RUNES + 1)))).toBe('invalid-secret');
    expect(await codeOf(() => sealSecret(root, 'a\ud800'))).toBe('invalid-secret');
    const empty = await sealSecret(root, '');
    expect(secretTextIsEmpty(empty)).toBe(true);
    expect(await codeOf(() => checkSecretFraming(empty.slice(1)))).toBe('encoding');
    const invalid = await sealSecretRaw(root, Uint8Array.of(0x63, 0xe9));
    expect(await codeOf(() => openSecret(root, invalid))).toBe('invalid-secret');
    expect(await sealSecret(root, 'x')).not.toBe(await sealSecret(root, 'x'));
  });
});
